import { Box, Grid, Skeleton, Stack, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';
import Person2TwoToneIcon from '@mui/icons-material/Person2TwoTone';
import { appColors } from '../../../../theme/appColors';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import { ICustomerData } from '../../../../core/Interface/customer.interface';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';

/* ── single stat tile ────────────────────────────────────────────────────── */
const StatTile: React.FC<{
  label: string;
  value: string;
  accent: string;
}> = ({ label, value, accent }) => (
  <Box
    sx={{
      background: alpha(accent, 0.06),
      border: `1px solid ${alpha(accent, 0.18)}`,
      borderRadius: '8px',
      px: 1,
      py: 0.75,
      textAlign: 'center',
    }}
  >
    <Typography
      sx={{
        color: alpha(NAVY, 0.5),
        fontSize: 9,
        fontWeight: 700,
        letterSpacing: '0.06em',
        textTransform: 'uppercase',
        lineHeight: 1.2,
      }}
    >
      {label}
    </Typography>
    <Typography
      sx={{
        color: accent,
        fontSize: 12,
        fontWeight: 800,
        fontVariantNumeric: 'tabular-nums',
        lineHeight: 1.3,
        mt: 0.25,
      }}
    >
      {value}
    </Typography>
  </Box>
);

/* ── component ───────────────────────────────────────────────────────────── */
const CustomerProfile = ({
  isLoading,
  customerData,
}: {
  isLoading: boolean;
  customerData?: ICustomerData;
}) => {
  const fmt = (value?: number) =>
    value != null ? getPriceFormatWithoutCurrency(value) : 'N/A';

  /* loading state */
  if (isLoading) {
    return (
      <Box sx={{ pb: 1.5 }}>
        <Stack
          alignItems="center"
          direction="row"
          gap={1}
          sx={{ mb: 1 }}
        >
          <Skeleton height={36} variant="circular" width={36} />
          <Stack direction="column" gap={0.5}>
            <Skeleton height={13} variant="text" width={110} />
            <Skeleton height={11} variant="text" width={80} />
          </Stack>
        </Stack>
        <Grid container spacing={0.75}>
          {[1, 2, 3].map((i) => (
            <Grid item key={i} xs={4}>
              <Skeleton height={42} sx={{ borderRadius: '8px' }} variant="rectangular" />
            </Grid>
          ))}
        </Grid>
      </Box>
    );
  }

  /* empty state */
  if (!customerData) {
    return (
      <Typography
        sx={{ color: appColors.royalBlue[60], fontSize: 12, fontWeight: 600, py: 1, textAlign: 'center' }}
      >
        No customer data available
      </Typography>
    );
  }

  /* loaded state */
  return (
    <Box sx={{ pb: 1 }}>
      {/* Name row */}
      <Stack
        alignItems="center"
        direction="row"
        gap={1}
        sx={{ mb: 1 }}
      >
        <Box
          sx={{
            alignItems: 'center',
            background: alpha(TEAL, 0.1),
            borderRadius: '8px',
            color: TEAL,
            display: 'flex',
            flexShrink: 0,
            height: 34,
            justifyContent: 'center',
            width: 34,
          }}
        >
          <Person2TwoToneIcon sx={{ fontSize: 20 }} />
        </Box>
        <Box>
          <Typography
            sx={{
              color: NAVY,
              fontSize: 13,
              fontWeight: 800,
              lineHeight: 1.2,
            }}
          >
            {customerData.name}
          </Typography>
          <Typography sx={{ color: '#94A3B8', fontSize: 10, fontWeight: 500 }}>
            Loyalty Program
          </Typography>
        </Box>
      </Stack>

      {/* Stats row */}
      <Grid container spacing={0.75}>
        <Grid item xs={4}>
          <StatTile
            accent={TEAL}
            label="Credit Limit"
            value={fmt(customerData.creditLimit)}
          />
        </Grid>
        <Grid item xs={4}>
          <StatTile
            accent="#7C3AED"
            label="Rewards"
            value={fmt(customerData.rewards)}
          />
        </Grid>
        <Grid item xs={4}>
          <StatTile
            accent="#2563EB"
            label="Cr. Balance"
            value={fmt(customerData.creditBalance)}
          />
        </Grid>
      </Grid>
    </Box>
  );
};

export default React.memo(CustomerProfile);
