import React from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Stack,
  Typography,
} from '@mui/material';
import WarningAmberRoundedIcon from '@mui/icons-material/WarningAmberRounded';
import { useTranslation } from 'react-i18next';

interface IMobile {
  open: boolean;
  openModel?: boolean;
  handleCloseDialog: (close: boolean) => void;
  handlePay: () => void;
  received?: number;
  total?: number;
}

const AlertPopup1: React.FC<IMobile> = ({
  openModel = false,
  handleCloseDialog,
  handlePay,
  received,
  total,
}) => {
  const { t } = useTranslation(['common', 'sales']);
  const [open] = React.useState(openModel);

  const handleClose = () => handleCloseDialog(false);
  const handlePayClick = () => { handlePay(); handleClose(); };

  return (
    <Dialog
      onClose={handleClose}
      open={open}
      PaperProps={{
        sx: {
          borderRadius: '12px',
          overflow: 'hidden',
          width: 440,
          maxWidth: 'calc(100vw - 32px)',
        },
      }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background: 'linear-gradient(135deg, #78350F 0%, #B45309 60%, #D97706 100%)',
            px: 3,
            py: 2,
          }}
        >
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '8px',
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
                flexShrink: 0,
              }}
            >
              <WarningAmberRoundedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                Alert
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                Payment confirmation required
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ px: 3, pt: 2.5, pb: 1 }}>
        <Typography sx={{ color: '#475569', fontSize: '0.92rem', lineHeight: 1.6 }}>
          Received amount is less than the total due. The remaining balance will be added to customer credit.
        </Typography>
        {received !== undefined && total !== undefined && (
          <Box
            sx={{
              background: '#FEF3C7',
              border: '1px solid #FCD34D',
              borderRadius: '8px',
              mt: 2,
              p: 1.5,
            }}
          >
            <Stack spacing={0.5}>
              <Stack direction="row" justifyContent="space-between">
                <Typography sx={{ color: '#92400E', fontSize: '0.82rem', fontWeight: 600 }}>
                  Total Amount
                </Typography>
                <Typography sx={{ color: '#92400E', fontSize: '0.82rem', fontWeight: 700 }}>
                  {total.toFixed(2)}
                </Typography>
              </Stack>
              <Stack direction="row" justifyContent="space-between">
                <Typography sx={{ color: '#92400E', fontSize: '0.82rem', fontWeight: 600 }}>
                  Received
                </Typography>
                <Typography sx={{ color: '#92400E', fontSize: '0.82rem', fontWeight: 700 }}>
                  {received.toFixed(2)}
                </Typography>
              </Stack>
              <Divider sx={{ borderColor: '#FCD34D', my: 0.25 }} />
              <Stack direction="row" justifyContent="space-between">
                <Typography sx={{ color: '#7C2D12', fontSize: '0.86rem', fontWeight: 700 }}>
                  Balance Due
                </Typography>
                <Typography sx={{ color: '#7C2D12', fontSize: '0.86rem', fontWeight: 700 }}>
                  {(total - received).toFixed(2)}
                </Typography>
              </Stack>
            </Stack>
          </Box>
        )}
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        <Button
          onClick={handleClose}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          {t('sales:cancel')}
        </Button>
        <Button
          autoFocus
          onClick={handlePayClick}
          sx={{
            background: 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 50%, #0F8B8D 100%)',
            borderRadius: '8px',
            boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
            color: '#fff',
            fontWeight: 700,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: 'linear-gradient(135deg, #0a1238 0%, #1a3070 50%, #0a7a7c 100%)' },
          }}
          variant="contained"
        >
          Pay
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default AlertPopup1;
