import React, { useEffect, useMemo, useState } from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import { Box, Grid, Stack, TextField, Typography, useMediaQuery } from '@mui/material';
import PersonOutlinedIcon from '@mui/icons-material/PersonOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useFormik } from 'formik';
import { useTranslation } from 'react-i18next';
import { useAppDispatch } from '../../../store/hooks';
import { useSelector } from 'react-redux';
import { addCustomer } from '../store/BasketSelector';
import { addCustomerDetailes } from '../store/BasketSlice';
import { IAddCustomer } from '../../../core/Interface/property.interface';
import { useNotifier } from '../../../core/Notifier';
import { useGetCustomerByMobileQuery } from '../../posApi';
import Autocomplete from '@mui/material/Autocomplete'; // Import Autocomplete component
import {  ICustomerMobileDatails } from '../../../core/Interface/customer.interface';

interface IMobile {
  title: string;
  openModel?: boolean;
  handleCloseDialog: (close: boolean) => void;
  customers: string;
}

const AddMobile: React.FC<IMobile> = ({
  title,
  openModel = false,
  handleCloseDialog,
}) => {
  const { t } = useTranslation(['common', 'sales']);
  const [open, setOpen] = useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const dispatch = useAppDispatch();
  const selectAddCustomer = useSelector(addCustomer);
  const { showErrorMessage } = useNotifier();
  const [customerNumber, setCustomerNumber] = useState<string>('');
  const [mobileOptions, setMobileOptions] = useState<string[]>([]);

  const { data: customerData, isFetching } = useGetCustomerByMobileQuery(
    customerNumber,
    {
      skip: customerNumber.length < 6,
    }
  );

  useEffect(() => {
    if (customerData) {
      const customers = (
        customerData.data as { customers: ICustomerMobileDatails[] }
      )?.customers;
      if (customers) {
        setMobileOptions(
          customers.map((customer: ICustomerMobileDatails) => customer.mobile)
        );
      }
    }
  }, [customerNumber, customerData]);

  const handleMobileNumberChange = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const { value } = event.target;
    setCustomerNumber(value);

    if (event) {
      formik.setFieldValue('mobile', value);

      // Update the customerName field if the selected mobile number matches
      // any customer's mobile number in the customerData
      if (customerData) {
        const customers = (
          customerData.data as { customers: ICustomerMobileDatails[] }
        ).customers;

        const matchedCustomer = customers.find(
          (customer: ICustomerMobileDatails) => customer.mobile === value
        );

        if (matchedCustomer) {
          formik.setFieldValue('customerName', matchedCustomer.name);
        } else {
          formik.setFieldValue('customerName', '');
        }
      }
    }
  };

  const handleClose = () => {
    setOpen(false);
    handleCloseDialog(false);
  };

  const validateMobileNumber = (value: string) => {
    if (value.startsWith('0')) {
      const mobileRegex = /^[0-9]{10}$/;
      return mobileRegex.test(value);
    } else {
      const mobileRegex = /^[1-9]{9}$/;
      return mobileRegex.test(value);
    }
  };

  const formik = useFormik({
    initialValues: {
      mobile: selectAddCustomer.mobile || '',
      customerName: selectAddCustomer.customerName || '',
    },
    onSubmit: async (values) => {
      console.info(values);
      try {
        if (!validateMobileNumber(values.mobile || '')) {
          showErrorMessage('Mobile number should be valid.');
          return;
        }
        const selectCustomer: IAddCustomer = values;
        dispatch(addCustomerDetailes(selectCustomer));
        handleClose();
      } catch (error) {
        showErrorMessage('Something went wrong');
      }
    },
  });

  const formValid = useMemo(() => {
    return (
      formik.values.mobile !== undefined &&
      formik.values.mobile.trim().length > 0
    );
  }, [formik.values.mobile]);

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          fullScreen={isMobile}
          fullWidth
          maxWidth="xs"
          onClose={handleClose}
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <PersonOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Add customer details</Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>
          <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
            <Box>
              {/* {JSON.stringify(customerData || {})} */}
              <Grid container>
                <Grid
                  item
                  xs={12}
                >
                  <FieldHeader title={t('sales:mobileNumber')} />

                  <Autocomplete
                    freeSolo
                    getOptionLabel={(option) => option}
                    loading={isFetching}
                    noOptionsText="Can't find number"
                    onChange={(event, value) => {
                      // When a suggestion is selected, find and update the corresponding name
                      if (value && customerData) {
                        const customers = (
                          customerData.data as {
                            customers: ICustomerMobileDatails[];
                          }
                        ).customers;

                        const matchedCustomer = customers.find(
                          (customer) => customer.mobile === value
                        );

                        if (matchedCustomer) {
                          formik.setFieldValue(
                            'mobile',
                            matchedCustomer.mobile
                          );
                          formik.setFieldValue(
                            'customerName',
                            matchedCustomer.name
                          );
                        }
                      }
                    }}
                    options={mobileOptions}
                    renderInput={(params) => (
                      <TextField
                        autoComplete="off"
                        {...params}
                        error={
                          formik.touched.mobile &&
                          !validateMobileNumber(formik.values.mobile || '')
                        }
                        helperText={
                          formik.touched.mobile &&
                          !validateMobileNumber(formik.values.mobile || '') && (
                            <span style={{ textTransform: 'none' }}>
                              Please enter valid mobile number.
                            </span>
                          )
                        }
                        inputProps={{
                          ...params.inputProps,
                          maxLength: 10,
                          type: 'tel',
                        }}
                        onBlur={() => formik.setFieldTouched('mobile', true)}
                        onChange={handleMobileNumberChange}
                        placeholder="Mobile Number"
                        sx={{ maxHeight: 40 }}
                      />
                    )}
                    sx={{ maxHeight: 40 }}
                    value={formik.values.mobile}
                  />
                </Grid>
                <Grid
                  item
                  sx={{ pt: 2 }}
                  xs={12}
                >
                  <FieldHeader title={t('sales:customername')} />

                  <TextField
                    autoComplete="off"
                    fullWidth
                    name="customerName"
                    onChange={formik.handleChange}
                    placeholder="Customer Name"
                    value={formik.values.customerName}
                    variant="outlined"
                  />
                </Grid>
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
              variant="outlined"
            >
              {t('sales:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid}
              onClick={(val) => {
                const selectCustomer: IAddCustomer = formik.values;
                dispatch(addCustomerDetailes(selectCustomer));
                handleClose();
              }}
              sx={{ background: HEADER_GRADIENT, borderRadius: '8px', boxShadow: '0 4px 14px rgba(15,29,77,0.25)', color: '#fff', fontWeight: 700, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { opacity: 0.9 }, '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' } }}
              type="submit"
              variant="contained"
            >
              {t('sales:add')}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(AddMobile);
