import { useMemo } from 'react';
import { useGetAllProductQuery, useGetUserQuery } from '../posApi';
import { IUserInfo } from '../../core/Interface/user.interface';
import { BasketItem } from './store/SalesRichBasketSlice';
import { useSelector } from 'react-redux';
import {
  selectBasket,
  selectBasketItems,
  selectDiscount,
} from './store/SalesRichBasketSelector';
import { IProductData, IProduct } from '../../core/Interface/product.interface';
import {
  ISaleRichReqPayload,
  ISaleRichItem,
} from '../../core/Interface/saleRich.interface';

const toFixedDown = (num: number): number => {
  return Math.floor(num * 100) / 100;
};

const useSalesRich = () => {
  const { data: companyData } = useGetUserQuery();

  const selectItem = useSelector(selectBasketItems);
  const selectDis = useSelector(selectDiscount);
  const selectBasketStore = useSelector(selectBasket);

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  const isImageEnabled = useMemo(() => {
    if (
      companyData?.data &&
      typeof companyData.data === 'object' &&
      'company' in companyData.data
    ) {
      return (
        (companyData.data as { company: { isImageEnabled: boolean } }).company
          .isImageEnabled ?? false
      );
    }
    return false;
  }, [companyData]);

  const { data, isLoading, isFetching } = useGetAllProductQuery({
    pageIndex: 0,
    pageSize: 5000,
    searchText: '',
  });

  const categoryMemo = useMemo(() => {
    const groupedData: Record<string, IProductData[]> = {};
    const apiData = data?.data as IProduct;
    if (!isLoading && apiData && apiData.records) {
      apiData.records.forEach((re) => {
        const categoryName = re.categoryName;
        if (!groupedData[categoryName]) {
          groupedData[categoryName] = [];
        }
        groupedData[categoryName].push(re);
      });
    }
    return groupedData;
  }, [data?.data, isLoading]);

  const calculateSummary = useMemo(() => {
    const subTotal = selectItem.reduce(getSubtotalSum, 0);
    const itemDiscount = selectItem.reduce(getDiscountSum, 0);
    const total = subTotal - itemDiscount;
    const rawInvoiceDiscount = selectDis.discountAsPercentage
      ? (total * (selectDis.discount ?? 0)) / 100
      : selectDis.discount ?? 0;
    // Clamp: discount can never exceed the remaining total (prevents negative net total when basket is empty)
    const invoiceDiscount = Math.min(rawInvoiceDiscount, Math.max(total, 0));
    const totalDiscount = itemDiscount + invoiceDiscount;
    const netTotal = Math.max(total - invoiceDiscount, 0);

    return {
      subTotal: toFixedDown(subTotal),
      discount: toFixedDown(totalDiscount),
      total: toFixedDown(total),
      itemDiscount: toFixedDown(itemDiscount),
      invoiceDiscount: toFixedDown(invoiceDiscount),
      netTotal: toFixedDown(netTotal),
    };
  }, [selectItem, selectDis.discount, selectDis.discountAsPercentage]);

  const salesDetails: ISaleRichReqPayload = {
    subTotal: calculateSummary.total,
    discount: calculateSummary.invoiceDiscount,
    totalDiscount: calculateSummary.discount,
    total: calculateSummary.netTotal,

    discountValue: selectDis.discount ?? 0,
    isDiscountPercentage: selectDis.discountAsPercentage,

    mobile: selectBasketStore.mobile ?? '',
    customerName: selectBasketStore.customerName ?? '',
    saleId: selectBasketStore.saleId,
    received: selectBasketStore.receivedAmount ?? 0,
    return: selectBasketStore.returnAmount ?? 0,
    balance: (selectBasketStore.receivedAmount ?? 0) - calculateSummary.netTotal,

    items: selectItem.map((item): ISaleRichItem => {
      const itemDiscount = item.isDiscountPercentage
        ? ((item.unitPrice * (item.defaultDiscountAmount ?? 0)) / 100) *
          item.count
        : (item.defaultDiscountAmount ?? 0) * item.count;

      const amountBeforeDiscount = item.unitPrice * item.count;
      const amountAfterDiscount = amountBeforeDiscount - itemDiscount;

      return {
        productId: item.id,
        productName: item.name,
        qty: item.count,
        unitPrice: item.unitPrice,
        amount: toFixedDown(amountAfterDiscount),
        discount: toFixedDown(itemDiscount),
        discountValue: item.defaultDiscountAmount ?? 0,
        isDiscountPercentage: item.isDiscountPercentage ?? false,
        amountAfterDiscount: toFixedDown(amountAfterDiscount),
      };
    }),
  };

  return {
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    categoryMemo,
    isImageEnabled,
    currencyCode,
    calculateSummary,
    salesDetails,
  };
};

export default useSalesRich;

function getDiscountSum(total: number, item: BasketItem) {
  if (!item.defaultDiscountAmount) return total;
  if (item.isDiscountPercentage) {
    return total + ((item.unitPrice * item.defaultDiscountAmount) / 100) * item.count;
  }
  return total + item.defaultDiscountAmount * item.count;
}
function getSubtotalSum(total: number, item: BasketItem) {
  return total + item.unitPrice * item.count;
}
