import React from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  Typography,
} from '@mui/material';
import PrintOutlinedIcon from '@mui/icons-material/PrintOutlined';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import { HEADER_GRADIENT } from '../../theme/appColors';

interface PrePrintPopupProps {
  open: boolean;
  handleClose: () => void;
  handlePrint: () => void;
  whatsappLink?: string;
  children: React.ReactNode;
}

const PrePrintPopup: React.FC<PrePrintPopupProps> = ({
  open,
  handleClose,
  handlePrint,
  whatsappLink,
  children,
}) => {
  const handleWhatsAppShare = () => {
    if (whatsappLink) window.open(whatsappLink, '_blank');
  };

  return (
    <Dialog
      fullWidth
      maxWidth="sm"
      onClose={handleClose}
      open={open}
      PaperProps={{
        sx: {
          borderRadius: '12px',
          overflow: 'hidden',
        },
      }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '8px',
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
                flexShrink: 0,
              }}
            >
              <PrintOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                Invoice Preview
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                Review before printing
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ px: 3, pt: 2.5, pb: 1 }}>
        {children}
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        {whatsappLink && (
          <Button
            onClick={handleWhatsAppShare}
            startIcon={<WhatsAppIcon sx={{ fontSize: 18 }} />}
            sx={{
              borderColor: '#22C55E',
              borderRadius: '8px',
              color: '#16A34A',
              fontWeight: 600,
              height: 40,
              px: 2.5,
              textTransform: 'none',
              '&:hover': { background: '#F0FDF4', borderColor: '#16A34A' },
            }}
            variant="outlined"
          >
            WhatsApp
          </Button>
        )}
        <Button
          onClick={handlePrint}
          startIcon={<PrintOutlinedIcon sx={{ fontSize: 17 }} />}
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: '8px',
            boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
            color: '#fff',
            fontWeight: 700,
            height: 40,
            px: 2.5,
            textTransform: 'none',
            '&:hover': { opacity: 0.9 },
          }}
          variant="contained"
        >
          Print
        </Button>
        <Button
          onClick={handleClose}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            px: 2.5,
            textTransform: 'none',
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default PrePrintPopup;
