import React from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  Typography,
} from '@mui/material';
import AccessTimeRoundedIcon from '@mui/icons-material/AccessTimeRounded';
import { useTranslation } from 'react-i18next';

interface IdleTimeoutPopupProps {
  open: boolean;
  onLogout: () => void;
  onStay: () => void;
}

const IdleTimeoutPopup: React.FC<IdleTimeoutPopupProps> = ({ open, onLogout, onStay }) => {
  const { t } = useTranslation(['common']);

  return (
    <Dialog
      onClose={() => {}}
      open={open}
      PaperProps={{
        sx: {
          borderRadius: '12px',
          overflow: 'hidden',
          width: 420,
          maxWidth: 'calc(100vw - 32px)',
        },
      }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background: 'linear-gradient(135deg, #7C2D12 0%, #C2410C 60%, #EA580C 100%)',
            px: 3,
            py: 2,
          }}
        >
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '8px',
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
                flexShrink: 0,
              }}
            >
              <AccessTimeRoundedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                Session Timeout
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                Your session is about to expire
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ px: 3, pt: 2.5, pb: 1 }}>
        <Typography sx={{ color: '#475569', fontSize: '0.92rem', lineHeight: 1.6 }}>
          Do you want to stay signed in?
        </Typography>
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        <Button
          onClick={onLogout}
          sx={{
            borderColor: '#FECACA',
            borderRadius: '8px',
            color: '#DC2626',
            fontWeight: 600,
            height: 40,
            minWidth: 120,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: '#FEF2F2', borderColor: '#F87171' },
          }}
          variant="outlined"
        >
          {t('common:no')} (Logout)
        </Button>
        <Button
          onClick={onStay}
          sx={{
            background: 'linear-gradient(135deg, #7C2D12 0%, #EA580C 100%)',
            borderRadius: '8px',
            boxShadow: '0 4px 14px rgba(234,88,12,0.3)',
            color: '#fff',
            fontWeight: 700,
            height: 40,
            minWidth: 120,
            px: 3,
            textTransform: 'none',
            '&:hover': { opacity: 0.9 },
          }}
          variant="contained"
        >
          {t('common:yes')} (Stay)
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default IdleTimeoutPopup;
