import {
  Box,
  CircularProgress,
  Grid,
  IconButton,
  Paper,
  Skeleton,
  Stack,
  styled,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import * as React from 'react';
import { useMemo } from 'react';
import { useGetAllForSaleQuery } from '../../posApi';
import { IProduct, IProductData } from '../../../core/Interface/product.interface';
import { useAppDispatch } from '../../../store/hooks';
import { addItem, removeBasket } from '../store/BasketSlice';
import { getPriceFormatWithoutCurrency } from '../../../core/utils';
import { useNavigate } from 'react-router-dom';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import { useTranslation } from 'react-i18next';
import AlertPopup from './Kgpopup';
import useScanDetection from 'use-scan-detection-react18';
import FindOrder from './FindOrder';
import { IJewelleryBasketItem } from '../../../core/Interface/saleJewellery.interface';
import Person3Icon from '@mui/icons-material/Person3';
import AddIcon from '@mui/icons-material/Add';
import InventoryOutlinedIcon from '@mui/icons-material/InventoryOutlined';
import RefreshIcon from '@mui/icons-material/Refresh';
import LocalOfferOutlinedIcon from '@mui/icons-material/LocalOfferOutlined';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import PointOfSaleIcon from '@mui/icons-material/PointOfSale';
import LockIcon from '@mui/icons-material/Lock';
import DeleteIcon from '@mui/icons-material/Delete';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import PrintIcon from '@mui/icons-material/Print';
import ShoppingBasketIcon from '@mui/icons-material/ShoppingBasket';
import SearchIcon from '@mui/icons-material/Search';
import ShoppingCartCheckoutIcon from '@mui/icons-material/ShoppingCartCheckout';
import CardGiftcardIcon from '@mui/icons-material/CardGiftcard';
import PercentIcon from '@mui/icons-material/Percent';
import NoteAltIcon from '@mui/icons-material/NoteAlt';

// ── Design tokens (exact match to SalesRich) ────────────────────────────────
const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const TILE_BG     = 'linear-gradient(145deg, #eef2ff 0%, #e0e7ff 100%)';
const TILE_BG_HVR = 'linear-gradient(145deg, #dde5ff 0%, #c7d6ff 100%)';
const TILE_BORDER = 'rgba(99,120,220,0.18)';
const TILE_NAV    = 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)';
const CAT_ACTIVE  = 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)';
const CAT_INACTIVE = 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)';
const L_TEAL   = 'linear-gradient(135deg, #ccfbf1 0%, #99f6e4 100%)';
const L_GREEN  = 'linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%)';
const L_AMBER  = 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)';
const L_BLUE   = 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)';
const L_PINK   = 'linear-gradient(135deg, #fce7f3 0%, #fbcfe8 100%)';
const L_INDIGO = 'linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%)';
const L_RED    = 'linear-gradient(135deg, #fee2e2 0%, #fecaca 100%)';
const L_PURPLE = 'linear-gradient(135deg, #f3e8ff 0%, #e9d5ff 100%)';

// ── Tile component matching SalesRich exactly ────────────────────────────────
const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  color: theme.palette.text.secondary,
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const btnLabel = (text: string, color = '#0F1D4D') => (
  <Typography sx={{ fontWeight: 700, fontSize: 11, color, mt: '2px' }}>
    {text}
  </Typography>
);

const CAT_MAX_COUNT_PER_ROW = 6;
const PRODUCT_MAX_COUNT_PER_ROW = 15;

interface SalesRightProps {
  onPay: () => void;
  onDiscount: () => void;
  isPayLoading?: boolean;
  hasItems: boolean;
  paymentStatus: boolean;
}

const SalesRight = ({ onPay, onDiscount, isPayLoading, hasItems }: SalesRightProps) => {
  const { t } = useTranslation(['sales']);
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { data, isLoading } = useGetAllForSaleQuery({ pageIndex: 0, pageSize: 5000, searchText: '' });

  const [selectedCat, setSelectedCat] = React.useState<string | null>(null);
  const [productPage, setProductPage] = React.useState(0);
  const [catPage, setCatPage] = React.useState(0);
  const [openFindOrder, setOpenFindOrder] = React.useState(false);
  const [selectedProduct, setSelectedProduct] = React.useState<IProductData | null>(null);
  const [openShowPopup, setOpenShowPopup] = React.useState(false);

  const productDataMemo = useMemo(() => data?.data as IProduct, [data?.data]);

  const uniqueCategories = useMemo(() => {
    const grouped: Record<string, boolean> = {};
    productDataMemo?.records?.forEach((r) => { grouped[r.categoryName] = true; });
    return Object.keys(grouped).sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
  }, [productDataMemo]);

  const filteredProducts = useMemo(() => {
    const all = productDataMemo?.records ?? [];
    return selectedCat ? all.filter((r) => r.categoryName === selectedCat) : all;
  }, [productDataMemo, selectedCat]);

  React.useEffect(() => { setProductPage(0); }, [selectedCat]);

  useScanDetection({
    onComplete: (code) => {
      const ret = code.replace('Shift', '');
      const products = productDataMemo?.records?.filter((r) => r.code.includes(ret));
      if (products?.length === 1) {
        dispatch(addItem({ ...products[0], count: 1 } as IJewelleryBasketItem));
      }
    },
  });

  const addItemToCard = (item: IProductData) => {
    setSelectedProduct(item);
    setOpenShowPopup(true);
  };

  const handleAdd = (
    calculatedValue: number | null,
    inputCount: number,
    goldData?: {
      goldWeightQty: number;
      goldWasteQty: number;
      goldCarrot: string;
      makingCharge: number;
      goldPrice8g: number;
    }
  ) => {
    if (selectedProduct && calculatedValue !== null) {
      const variantId = `${selectedProduct.id}__v${Math.floor(Math.random() * 20) + 10}`;
      const basketItem: IJewelleryBasketItem = {
        ...selectedProduct,
        id: variantId,
        unitPrice: calculatedValue,
        calculatedUnitPrice: calculatedValue,
        count: inputCount || 1,
        goldWeightQty: goldData?.goldWeightQty ?? 0,
        goldWasteQty: goldData?.goldWasteQty ?? 0,
        goldCarrot: goldData?.goldCarrot ?? '22K',
        makingCharge: goldData?.makingCharge ?? 0,
        goldPrice8g: goldData?.goldPrice8g ?? 0,
      };
      dispatch(addItem(basketItem));
      setOpenShowPopup(false);
    }
  };

  // Category pagination
  const totalCatPages = Math.ceil(uniqueCategories.length / CAT_MAX_COUNT_PER_ROW);
  const visibleCats = uniqueCategories.slice(
    catPage * CAT_MAX_COUNT_PER_ROW,
    (catPage + 1) * CAT_MAX_COUNT_PER_ROW
  );

  // Product pagination — PRODUCT_MAX_COUNT_PER_ROW per page + 1 nav = fills 2 rows of 8
  const productPageData = useMemo(() => {
    const total = filteredProducts.length;
    const startIdx = productPage * PRODUCT_MAX_COUNT_PER_ROW;
    const slice = filteredProducts.slice(startIdx, startIdx + PRODUCT_MAX_COUNT_PER_ROW);
    return { slice, total, startIdx };
  }, [filteredProducts, productPage]);

  const fillerCount = Math.max(0, PRODUCT_MAX_COUNT_PER_ROW - productPageData.slice.length);

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <Box
      sx={{
        '--tile-h': 'calc((100vh - 124px) / 7)',
        height: '100%',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
        gap: '3px',
        pt: '2px',
        pb: '4px',
        px: '4px',
      }}
    >
      {/* ═══════ SECTION 1: Category + Products (rows 1-3) ═══════ */}
      <Box sx={{ flex: '0 0 auto' }}>

        {/* Row 1 — Category tiles */}
        <Grid container spacing={1} sx={{ cursor: 'pointer' }}>

          {/* "ALL" tile — dark navy */}
          <Grid item key="cat_all" md={1.5} sm={1.5} xs={4}>
            <Item
              onClick={() => setSelectedCat(null)}
              sx={{
                background: selectedCat === null ? CAT_ACTIVE : CAT_INACTIVE,
                border: selectedCat === null ? '2px solid #99f6e4' : '2px solid transparent',
                boxShadow: selectedCat === null ? '0 4px 14px rgba(20,30,85,0.35)' : 'none',
              }}
            >
              <Typography
                sx={{
                  fontWeight: 700,
                  fontSize: 11,
                  color: selectedCat === null ? '#fff' : NAVY,
                  textAlign: 'center',
                  letterSpacing: '0.3px',
                  lineHeight: 1.2,
                  px: 0.5,
                }}
              >
                ALL
              </Typography>
            </Item>
          </Grid>

          {/* Category tiles */}
          {!isLoading && visibleCats.map((cat) => (
            <Grid item key={cat + '-cat'} md={1.5} sm={1.5} xs={4}>
              <Item
                onClick={() => setSelectedCat(selectedCat === cat ? null : cat)}
                sx={{
                  background: selectedCat === cat ? CAT_ACTIVE : CAT_INACTIVE,
                  border: selectedCat === cat ? '2px solid #99f6e4' : '2px solid transparent',
                  boxShadow: selectedCat === cat ? '0 4px 14px rgba(20,30,85,0.35)' : 'none',
                }}
              >
                <Stack alignItems="center" direction="column">
                  <Typography
                    sx={{
                      fontWeight: 700,
                      fontSize: 11,
                      color: selectedCat === cat ? '#fff' : NAVY,
                      textAlign: 'center',
                      letterSpacing: '0.3px',
                      lineHeight: 1.2,
                      px: 0.5,
                    }}
                  >
                    {cat}
                  </Typography>
                </Stack>
              </Item>
            </Grid>
          ))}

          {/* Filler tiles */}
          {!isLoading && visibleCats.length < CAT_MAX_COUNT_PER_ROW &&
            Array.from(Array(CAT_MAX_COUNT_PER_ROW - visibleCats.length).keys()).map((k) => (
              <Grid item key={'cat_ph_' + k} md={1.5} sm={1.5} xs={4}>
                <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default', boxShadow: 'none' }} />
              </Grid>
            ))}

          {/* Loading skeletons */}
          {isLoading && Array.from(Array(CAT_MAX_COUNT_PER_ROW).keys()).map((k) => (
            <Grid item key={'cat_sk_' + k} md={1.5} sm={1.5} xs={4}>
              <Skeleton height="var(--tile-h)" sx={{ borderRadius: '10px' }} variant="rectangular" />
            </Grid>
          ))}

          {/* Nav tile — always present */}
          {!isLoading && (
            <Grid item key="cat_nav" md={1.5} sm={1.5} xs={4}>
              <Item sx={{ background: TILE_NAV, cursor: 'default' }}>
                <Grid container>
                  <Grid item sm={6}>
                    <IconButton
                      disabled={catPage <= 0}
                      onClick={() => setCatPage((p) => p - 1)}
                      size="small"
                      sx={{ color: '#fff', '&:disabled': { color: 'rgba(255,255,255,0.3)' } }}
                    >
                      <ArrowBackIosNewIcon sx={{ fontSize: 22 }} />
                    </IconButton>
                  </Grid>
                  <Grid item sm={6}>
                    <IconButton
                      disabled={catPage >= totalCatPages - 1}
                      onClick={() => setCatPage((p) => p + 1)}
                      size="small"
                      sx={{ color: '#fff', '&:disabled': { color: 'rgba(255,255,255,0.3)' } }}
                    >
                      <ArrowForwardIosIcon sx={{ fontSize: 22 }} />
                    </IconButton>
                  </Grid>
                </Grid>
              </Item>
            </Grid>
          )}
        </Grid>

        {/* Rows 2 & 3 — Product tiles */}
        <Box sx={{ mt: '4px' }}>
          <Grid container spacing={1}>
            {/* Product tiles */}
            {!isLoading && productPageData.slice.map((p) => (
              <Grid item key={p.id} md={1.5} sm={1.5} xs={4}>
                <Item
                  onClick={() => addItemToCard(p)}
                  sx={{
                    background: TILE_BG,
                    border: `1px solid ${TILE_BORDER}`,
                    boxShadow: 'none',
                    transition: 'background 0.15s, box-shadow 0.15s',
                    '&:hover': {
                      background: TILE_BG_HVR,
                      boxShadow: `0 3px 10px ${alpha(NAVY, 0.12)}`,
                    },
                  }}
                >
                  <Stack alignItems="center" direction="column" sx={{ px: 0.5 }}>
                    <Typography
                      sx={{
                        color: NAVY,
                        fontSize: 11,
                        fontWeight: 700,
                        lineHeight: 1.2,
                        mb: '2px',
                        textAlign: 'center',
                      }}
                    >
                      {p.name.length > 16 ? p.name.substring(0, 16) + '…' : p.name}
                    </Typography>
                    <Typography
                      sx={{
                        color: TEAL,
                        fontSize: 11,
                        fontVariantNumeric: 'tabular-nums',
                        fontWeight: 800,
                      }}
                    >
                      {getPriceFormatWithoutCurrency(p.unitPrice)}
                    </Typography>
                  </Stack>
                </Item>
              </Grid>
            ))}

            {/* Filler tiles */}
            {!isLoading && Array.from(Array(fillerCount).keys()).map((k) => (
              <Grid item key={'prod_ph_' + k} md={1.5} sm={1.5} xs={4}>
                <Item
                  sx={{
                    background: '#eef2ff',
                    border: `1px solid ${TILE_BORDER}`,
                    boxShadow: 'none',
                    cursor: 'default',
                    opacity: 0.4,
                  }}
                />
              </Grid>
            ))}

            {/* Nav tile — always present */}
            {!isLoading && (
              <Grid item key="prod_nav" md={1.5} sm={1.5} xs={4}>
                <Item sx={{ background: TILE_NAV, cursor: 'default' }}>
                  <Grid container sx={{ cursor: 'pointer' }}>
                    <Grid item sm={6}>
                      <IconButton
                        disabled={productPage <= 0}
                        onClick={() => setProductPage((p) => p - 1)}
                        size="small"
                        sx={{ color: '#fff', '&:disabled': { color: 'rgba(255,255,255,0.25)' } }}
                      >
                        <ArrowBackIosNewIcon sx={{ fontSize: 22 }} />
                      </IconButton>
                    </Grid>
                    <Grid item sm={6}>
                      <IconButton
                        disabled={
                          productPageData.startIdx + PRODUCT_MAX_COUNT_PER_ROW >= productPageData.total
                        }
                        onClick={() => setProductPage((p) => p + 1)}
                        size="small"
                        sx={{ color: '#fff', '&:disabled': { color: 'rgba(255,255,255,0.25)' } }}
                      >
                        <ArrowForwardIosIcon sx={{ fontSize: 22 }} />
                      </IconButton>
                    </Grid>
                  </Grid>
                </Item>
              </Grid>
            )}

            {/* Loading skeletons */}
            {isLoading && Array.from({ length: 16 }, (_, i) => i + 1).map((item) => (
              <Grid item key={'prod_sk_' + item} md={1.5} sm={1.5} xs={4}>
                <Skeleton height="var(--tile-h)" sx={{ borderRadius: '10px' }} variant="rectangular" />
              </Grid>
            ))}
          </Grid>
        </Box>
      </Box>

      {/* ═══════ SECTION 2: FourthSection — Customer + placeholders + Orders (row 4) ═══════ */}
      <Box sx={{ flex: '0 0 auto', mt: '4px' }}>
        <Grid container spacing={1}>

          {/* Customer */}
          <Grid item key="fourth_customer" md={1.5} sm={1.5} xs={4}>
            <Item
              sx={{
                background: L_PURPLE,
                position: 'relative',
              }}
            >
              <AddIcon
                sx={{ fontSize: 16, color: '#7c3aed', position: 'absolute', top: 7, right: 7, opacity: 0.9 }}
              />
              <Stack alignItems="center" direction="column">
                <Person3Icon sx={{ fontSize: 28, color: '#7c3aed' }} />
                <Typography sx={{ fontWeight: 700, fontSize: 11, color: NAVY, mt: '2px' }}>
                  Customer
                </Typography>
              </Stack>
            </Item>
          </Grid>

          {/* 5 placeholder tiles */}
          {['ph1', 'ph2', 'ph3', 'ph4', 'ph5'].map((k) => (
            <Grid item key={'fourth_' + k} md={1.5} sm={1.5} xs={4}>
              <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default' }} />
            </Grid>
          ))}

          {/* Orders tile */}
          <Grid item key="fourth_orders" md={1.5} sm={1.5} xs={4}>
            <Item
              onClick={() => setOpenFindOrder(true)}
              sx={{ background: L_TEAL }}
            >
              <Stack alignItems="center" direction="column">
                <InventoryOutlinedIcon sx={{ fontSize: 26, color: TEAL }} />
                {btnLabel('Orders')}
              </Stack>
            </Item>
          </Grid>

          {/* 1 filler */}
          <Grid item key="fourth_ph6" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default' }} />
          </Grid>
        </Grid>
      </Box>

      {/* ═══════ SECTION 3: FifthSection — Action tiles (row 5) ═══════ */}
      <Box sx={{ flex: '0 0 auto', mt: '4px' }}>
        <Grid container spacing={1}>

          {/* Tile 1 — Stock & Price style (teal) */}
          <Grid item key="fifth_1" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: L_TEAL, position: 'relative', opacity: 0.38, cursor: 'default' }}>
              <SearchIcon
                sx={{ fontSize: 14, color: 'rgba(15,29,77,0.4)', position: 'absolute', top: 7, right: 7 }}
              />
              <Stack alignItems="center" direction="column">
                <ShoppingBasketIcon sx={{ fontSize: 26, color: TEAL }} />
                {btnLabel('Valuation')}
              </Stack>
            </Item>
          </Grid>

          {/* Tile 2 — Refresh (blue) */}
          <Grid item key="fifth_2" md={1.5} sm={1.5} xs={4}>
            <Item
              onClick={hasItems ? () => dispatch(removeBasket()) : undefined}
              sx={{ background: L_BLUE, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
            >
              <Stack alignItems="center" direction="column">
                <RefreshIcon sx={{ fontSize: 26, color: '#1d4ed8' }} />
                {btnLabel('Refresh', '#1e3a8a')}
              </Stack>
            </Item>
          </Grid>

          {/* Tile 3 — Clear (green) */}
          <Grid item key="fifth_3" md={1.5} sm={1.5} xs={4}>
            <Item
              onClick={hasItems ? () => dispatch(removeBasket()) : undefined}
              sx={{ background: L_GREEN, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
            >
              <Stack alignItems="center" direction="column">
                <ShoppingCartCheckoutIcon sx={{ fontSize: 26, color: '#16a34a' }} />
                {btnLabel(t('sales:clear'), '#14532d')}
              </Stack>
            </Item>
          </Grid>

          {/* Tile 4 — placeholder (pink) */}
          <Grid item key="fifth_4" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: L_PINK, opacity: 0.38, cursor: 'default' }}>
              <Stack alignItems="center" direction="column">
                <CardGiftcardIcon sx={{ fontSize: 26, color: '#db2777' }} />
                {btnLabel('Gift Card', '#831843')}
              </Stack>
            </Item>
          </Grid>

          {/* Tile 5 — Discount (amber) */}
          <Grid item key="fifth_5" md={1.5} sm={1.5} xs={4}>
            <Item
              onClick={hasItems ? onDiscount : undefined}
              sx={{ background: L_AMBER, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
            >
              <Stack alignItems="center" direction="column">
                <PercentIcon sx={{ fontSize: 26, color: '#d97706' }} />
                {btnLabel(t('sales:dic'), '#92400e')}
              </Stack>
            </Item>
          </Grid>

          {/* Tile 6 — placeholder */}
          <Grid item key="fifth_6" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default' }}>
              <Stack alignItems="center" direction="column">
                <LocalOfferOutlinedIcon sx={{ fontSize: 26, color: 'rgba(148,163,184,0.5)' }} />
              </Stack>
            </Item>
          </Grid>

          {/* Tile 7 — placeholder (indigo) */}
          <Grid item key="fifth_7" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: L_INDIGO, opacity: 0.38, cursor: 'default' }}>
              <Stack alignItems="center" direction="column">
                <NoteAltIcon sx={{ fontSize: 26, color: '#4f46e5' }} />
                {btnLabel('Notes', '#312e81')}
              </Stack>
            </Item>
          </Grid>

          {/* Tile 8 — Back (blue) */}
          <Grid item key="fifth_8" md={1.5} sm={1.5} xs={4}>
            <Item onClick={() => navigate('/dashboard')} sx={{ background: L_BLUE }}>
              <Stack alignItems="center" direction="column">
                <ArrowBackIcon sx={{ fontSize: 26, color: '#1E3A8A' }} />
                {btnLabel('Back')}
              </Stack>
            </Item>
          </Grid>
        </Grid>
      </Box>

      {/* ═══════ SECTION 4: LastSection — misc tiles + PAY (row 6) ═══════ */}
      <Box sx={{ flex: '0 0 auto', mt: '4px' }}>
        <Grid container spacing={1}>

          {/* Hold (amber) — placeholder */}
          <Grid item key="last_01" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: L_AMBER, opacity: 0.35, cursor: 'default' }}>
              <Stack alignItems="center" direction="column">
                <LockIcon sx={{ fontSize: 26, color: '#d97706' }} />
                {btnLabel('Hold')}
              </Stack>
            </Item>
          </Grid>

          {/* Delete (red) */}
          <Grid item key="last_02" md={1.5} sm={1.5} xs={4}>
            <Item
              onClick={hasItems ? () => dispatch(removeBasket()) : undefined}
              sx={{
                background: L_RED,
                opacity: hasItems ? 1 : 0.35,
                cursor: hasItems ? 'pointer' : 'default',
              }}
            >
              <Stack alignItems="center" direction="column">
                <DeleteIcon sx={{ fontSize: 26, color: '#DC2626' }} />
                {btnLabel('Delete')}
              </Stack>
            </Item>
          </Grid>

          {/* Pay Credit (purple) — placeholder */}
          <Grid item key="last_03" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: L_PURPLE, opacity: 0.35, cursor: 'default' }}>
              <Stack alignItems="center" direction="column">
                <AttachMoneyIcon sx={{ fontSize: 26, color: '#7c3aed' }} />
                {btnLabel('Pay Credit')}
              </Stack>
            </Item>
          </Grid>

          {/* WhatsApp (green) — placeholder */}
          <Grid item key="last_04" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: L_GREEN, opacity: 0.35, cursor: 'default' }}>
              <Stack alignItems="center" direction="column">
                <WhatsAppIcon sx={{ fontSize: 26, color: '#16a34a' }} />
                {btnLabel('WhatsApp')}
              </Stack>
            </Item>
          </Grid>

          {/* Last Print (amber) — placeholder */}
          <Grid item key="last_05" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: L_AMBER, opacity: 0.35, cursor: 'default' }}>
              <Stack alignItems="center" direction="column">
                <PrintIcon sx={{ fontSize: 26, color: '#d97706' }} />
                {btnLabel('Last Print')}
              </Stack>
            </Item>
          </Grid>

          {/* Order (blue) — placeholder */}
          <Grid item key="last_06" md={1.5} sm={1.5} xs={4}>
            <Item sx={{ background: L_BLUE, opacity: 0.35, cursor: 'default' }}>
              <Stack alignItems="center" direction="column">
                <PrintIcon sx={{ fontSize: 26, color: '#1d4ed8' }} />
                {btnLabel('Order', '#1e3a8a')}
              </Stack>
            </Item>
          </Grid>

          {/* PAY — double width (md=3), exact SalesRich style */}
          <Grid item key="last_pay" md={3} sm={3} xs={4}>
            <Item
              onClick={hasItems ? onPay : undefined}
              sx={{
                background: hasItems
                  ? 'linear-gradient(135deg, #0F8B8D 0%, #0F1D4D 100%)'
                  : 'rgba(148,163,184,0.25)',
                opacity: hasItems ? 1 : 0.35,
                cursor: hasItems ? 'pointer' : 'default',
                boxShadow: hasItems ? '0 4px 14px rgba(15,139,141,0.35)' : 'none',
              }}
            >
              {isPayLoading ? (
                <CircularProgress size={22} sx={{ color: '#fff' }} />
              ) : (
                <Stack alignItems="center" direction="row" spacing={1}>
                  <PointOfSaleIcon sx={{ fontSize: 32, color: '#fff' }} />
                  <Typography sx={{ fontWeight: 900, fontSize: 20, color: '#fff', letterSpacing: '0.5px' }}>
                    PAY
                  </Typography>
                </Stack>
              )}
            </Item>
          </Grid>
        </Grid>
      </Box>

      {/* ── Dialogs ─────────────────────────────────────────────────────── */}
      {selectedProduct && openShowPopup && (
        <AlertPopup
          handleAdd={handleAdd}
          handleCloseAlert={() => setOpenShowPopup(false)}
          open={openShowPopup}
          product={selectedProduct}
        />
      )}

      <FindOrder
        handleClose={() => setOpenFindOrder(false)}
        open={openFindOrder}
        products={typeof data?.data === 'object' ? (data.data as IProduct).records : []}
      />
    </Box>
  );
};

export default React.memo(SalesRight);
