import CategoryOutlinedIcon from '@mui/icons-material/CategoryOutlined';
import CloudUploadOutlinedIcon from '@mui/icons-material/CloudUploadOutlined';
import Inventory2OutlinedIcon from '@mui/icons-material/Inventory2Outlined';
import * as React from 'react';
import { useMemo } from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  FormControlLabel,
  Grid,
  MenuItem,
  Select,
  SelectChangeEvent,
  Slide,
  Stack,
  Switch,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { TransitionProps } from '@mui/material/transitions';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { DatePicker, LocalizationProvider } from '@mui/x-date-pickers';
import dayjs from 'dayjs';
import { useFormik } from 'formik';
import { useTranslation } from 'react-i18next';
import { IProductData } from '../../../core/Interface/product.interface';
import { useNotifier } from '../../../core/Notifier';
import { useAppDispatch } from '../../../store/hooks';
import { restore } from '../../../store/posSlice';
import { uploadImage } from '../../../core/utils';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { useGetCategoryQuery, useSaveProductMutation } from '../../posApi';

interface INewProduct {
  openModel?: boolean;
  title: string;
  handleCloseDialog: () => void;
  data?: IProductData;
  isImageEnabled: boolean;
}

const inputFieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(appColors.white, 0.92),
    borderRadius: '4px',
    '& fieldset': {
      borderColor: alpha(appColors.blueGreyishLight[80], 0.16),
    },
    '&:hover fieldset': { borderColor: alpha('#2563EB', 0.28) },
    '&.Mui-focused': {
      boxShadow: `0 0 0 4px ${alpha('#2563EB', 0.10)}`,
    },
    '&.Mui-focused fieldset': { borderColor: '#2563EB' },
  },
};

const labelSx = {
  color: '#142352',
  fontSize: '0.82rem',
  fontWeight: 700,
  mb: 0.6,
};

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & {
    children: React.ReactElement<string, string>;
  },
  ref: React.Ref<unknown>
) {
  return (
    <Slide
      direction="up"
      ref={ref}
      {...props}
    />
  );
});

// eslint-disable-next-line react/no-multi-comp
const NewProduct = ({
  title,
  openModel = true,
  handleCloseDialog,
  data,
  isImageEnabled,
}: INewProduct) => {
  const { t } = useTranslation(['common', 'product', 'category']);
  const [open] = React.useState(openModel);
  const [saveProduct, { isLoading }] = useSaveProductMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { data: catData } = useGetCategoryQuery({
    pageIndex: 0,
    pageSize: 20,
    searchText: '',
  });
  const dispatch = useAppDispatch();

  const [selectedImage, setSelectedImage] = React.useState<
    File | undefined
  >(undefined);
  const [isImageUploading, setIsImageUploading] = React.useState(false);

  const categoryList = useMemo(
    () => (catData?.data as IProductData[]) ?? [],
    [catData?.data]
  );

  const formik = useFormik({
    initialValues: {
      name: data?.name ?? '',
      code: data?.code ?? '',
      category: data?.categoryId ?? '',
      unitPrice: data?.unitPrice ?? '',
      maxDiscountAmount: data?.maxDiscountAmount ?? '',
      stockAlertQty: data?.stockAlertQty ?? '',
      reOrderQty: data?.reOrderQty ?? '',
      defaultDiscountAmount: data?.defaultDiscountAmount ?? '',
      expiryDate: data?.expiryDate ?? '',
      isEnabled: data?.isEnabled ?? true,
      isKgOrLitre: data?.isKgOrLitre ?? false,
      isOnlineOrder: data?.isOnlineOrder ?? false,
    },
    onSubmit: async (values) => {
      try {
        let imageUrl: string | undefined = data?.imageUrl;
        if (selectedImage) {
          setIsImageUploading(true);
          imageUrl = (await uploadImage(selectedImage)) || '';
          setIsImageUploading(false);
        }

        const temData: Record<string, unknown> = {
          code: values.code,
          name: values.name,
          imageUrl,
          categoryId: values.category,
          unitPrice: values.unitPrice,
          maxDiscountAmount: values.maxDiscountAmount,
          stockAlertQty: values.stockAlertQty,
          reOrderQty: values.reOrderQty,
          defaultDiscountAmount: values.defaultDiscountAmount,
          expiryDate: values.expiryDate
            ? dayjs(values.expiryDate).format('YYYY-MM-DD')
            : '',
          isEnabled: values.isEnabled,
          isKgOrLitre: values.isKgOrLitre,
          isOnlineOrder: values.isOnlineOrder,
        };
        if (data?.id) temData.id = data.id;

        const res = await saveProduct(temData).unwrap();
        if (!res.status) {
          showErrorMessage(res.message);
        } else {
          showMessage(res.message);
          dispatch(restore());
          handleCloseDialog();
        }
      } catch (error) {
        setIsImageUploading(false);
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(
    () => !!formik.values.name?.trim() && !!formik.values.code?.trim(),
    [formik.values.name, formik.values.code]
  );

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    setSelectedImage(files && files.length > 0 ? files[0] : undefined);
  };

  const handleCategoryChange = (event: SelectChangeEvent) => {
    formik.setFieldValue('category', event.target.value);
  };

  const buttonText = data ? t('common:update') : t('common:create');
  const isBusy = isLoading || isImageUploading;
  const vals = formik.values as Record<string, unknown>;

  return (
    <Dialog
      PaperProps={{
        component: 'form',
        noValidate: true,
        onSubmit: formik.handleSubmit,
        sx: {
          borderRadius: '12px',
          overflow: 'hidden',
        },
      }}
      TransitionComponent={Transition}
      fullWidth
      maxWidth="sm"
      onClose={() => {
        dispatch(restore());
        handleCloseDialog();
      }}
      open={open}
    >
      {/* Header */}
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack
            alignItems="center"
            direction="row"
            spacing={1.5}
          >
            <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
              <Inventory2OutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Create or edit product</Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      {/* Body */}
      <DialogContent>
        <Box>
          <Grid
            container
            spacing={2}
          >
            {/* Code */}
            <Grid
              item
              sm={6}
              xs={12}
            >
              <Typography sx={labelSx}>Code d</Typography>
              <TextField
                autoComplete="off"
                fullWidth
                placeholder={t('product:title.code')}
                size="small"
                sx={inputFieldSx}
                {...formik.getFieldProps('code')}
              />
            </Grid>

            {/* Name */}
            <Grid
              item
              sm={6}
              xs={12}
            >
              <Typography sx={labelSx}>{t('product:title.name')}</Typography>
              <TextField
                autoComplete="off"
                fullWidth
                placeholder={t('product:title.name')}
                size="small"
                sx={inputFieldSx}
                {...formik.getFieldProps('name')}
              />
            </Grid>

            {/* Category */}
            <Grid
              item
              sm={6}
              xs={12}
            >
              <Typography sx={labelSx}>
                {t('product:title.category')}
              </Typography>
              <Select
                displayEmpty
                fullWidth
                onChange={handleCategoryChange}
                renderValue={(v) => {
                  if (!v) {
                    return (
                      <Typography
                        sx={{
                          color: alpha('#142352', 0.35),
                          fontSize: 14,
                        }}
                      >
                        Select category
                      </Typography>
                    );
                  }
                  const cat = categoryList.find((c) => c.id === v);
                  return (
                    <Stack
                      alignItems="center"
                      direction="row"
                      spacing={0.75}
                    >
                      <CategoryOutlinedIcon
                        sx={{ color: '#2563EB', fontSize: 16 }}
                      />
                      <span>{cat?.name ?? v}</span>
                    </Stack>
                  );
                }}
                size="small"
                sx={{
                  ...inputFieldSx,
                  '& .MuiSelect-select': { fontSize: 14 },
                }}
                value={formik.values.category}
              >
                {categoryList.map((val, idx) => (
                  <MenuItem
                    key={idx}
                    value={val.id}
                  >
                    {val.name}
                  </MenuItem>
                ))}
              </Select>
            </Grid>

            {/* Unit Price */}
            <Grid
              item
              sm={6}
              xs={12}
            >
              <Typography sx={labelSx}>
                {t('product:title.unitPrice')}
              </Typography>
              <TextField
                InputProps={{ inputProps: { min: 0 } }}
                autoComplete="off"
                fullWidth
                inputProps={{ step: 'any' }}
                placeholder="0.00"
                size="small"
                sx={inputFieldSx}
                type="number"
                {...formik.getFieldProps('unitPrice')}
              />
            </Grid>

            {/* Max Discount */}
            <Grid
              item
              sm={6}
              xs={12}
            >
              <Typography sx={labelSx}>
                {t('product:title.maxDiscountAmount')}
              </Typography>
              <TextField
                InputProps={{ inputProps: { min: 0 } }}
                autoComplete="off"
                fullWidth
                inputProps={{ step: 'any' }}
                placeholder="0.00"
                size="small"
                sx={inputFieldSx}
                type="number"
                {...formik.getFieldProps('maxDiscountAmount')}
              />
            </Grid>

            {/* Default Discount */}
            <Grid
              item
              sm={6}
              xs={12}
            >
              <Typography sx={labelSx}>
                {t('product:title.defaultDiscountAmount')}
              </Typography>
              <TextField
                InputProps={{ inputProps: { min: 0 } }}
                autoComplete="off"
                fullWidth
                inputProps={{ step: 'any' }}
                placeholder="0.00"
                size="small"
                sx={inputFieldSx}
                type="number"
                {...formik.getFieldProps('defaultDiscountAmount')}
              />
            </Grid>

            {/* Stock Alert Qty */}
            <Grid
              item
              sm={6}
              xs={12}
            >
              <Typography sx={labelSx}>
                {t('product:title.stockAlertQty')}
              </Typography>
              <TextField
                InputProps={{ inputProps: { min: 0 } }}
                autoComplete="off"
                fullWidth
                inputProps={{ step: 'any' }}
                placeholder="0"
                size="small"
                sx={inputFieldSx}
                type="number"
                {...formik.getFieldProps('stockAlertQty')}
              />
            </Grid>

            {/* Reorder Qty */}
            <Grid
              item
              sm={6}
              xs={12}
            >
              <Typography sx={labelSx}>
                {t('product:title.reOrderQty')}
              </Typography>
              <TextField
                InputProps={{ inputProps: { min: 0 } }}
                autoComplete="off"
                fullWidth
                inputProps={{ step: 'any' }}
                placeholder="0"
                size="small"
                sx={inputFieldSx}
                type="number"
                {...formik.getFieldProps('reOrderQty')}
              />
            </Grid>

            {/* Expiry Date */}
            <Grid
              item
              xs={12}
            >
              <Typography sx={labelSx}>
                {t('product:title.expiryDate')}
              </Typography>
              <LocalizationProvider dateAdapter={AdapterDayjs}>
                <DatePicker
                  InputProps={{ sx: { height: '40px', ...inputFieldSx } }}
                  inputFormat="DD-MM-YYYY"
                  minDate={dayjs()}
                  onChange={(date) =>
                    formik.setFieldValue('expiryDate', date)
                  }
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      fullWidth
                      inputProps={{
                        ...params.inputProps,
                        readOnly: true,
                      }}
                      size="small"
                      sx={{ ...inputFieldSx }}
                    />
                  )}
                  value={formik.values.expiryDate || null}
                  views={['day', 'month', 'year']}
                />
              </LocalizationProvider>
            </Grid>

            {/* Toggles */}
            <Grid
              item
              xs={12}
            >
              <Box
                sx={{
                  background: alpha('#2563EB', 0.03),
                  border: `1px solid ${alpha(
                    appColors.blueGreyishLight[80],
                    0.14
                  )}`,
                  borderRadius: '6px',
                  display: 'flex',
                  flexWrap: 'wrap',
                  gap: 2,
                  px: 2,
                  py: 1.5,
                }}
              >
                {[
                  {
                    field: 'isEnabled',
                    label: t('product:title.isEnabled'),
                  },
                  {
                    field: 'isKgOrLitre',
                    label: t('product:title.isKgOrLitre'),
                  },
                  {
                    field: 'isOnlineOrder',
                    label: t('product:title.isOnlineOrder'),
                  },
                ].map(({ field, label }) => (
                  <FormControlLabel
                    control={
                      <Switch
                        checked={!!vals[field]}
                        name={field}
                        onChange={formik.handleChange}
                        size="small"
                        sx={{
                          '& .MuiSwitch-switchBase.Mui-checked': {
                            color: '#2563EB',
                          },
                          '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track':
                            {
                              backgroundColor: alpha('#2563EB', 0.5),
                            },
                        }}
                      />
                    }
                    key={field}
                    label={
                      <Typography
                        sx={{
                          color: '#142352',
                          fontSize: '0.82rem',
                          fontWeight: 600,
                        }}
                      >
                        {label}
                      </Typography>
                    }
                    sx={{ m: 0 }}
                  />
                ))}
              </Box>
            </Grid>

            {/* Image upload */}
            {isImageEnabled && (
              <Grid
                item
                xs={12}
              >
                <Typography sx={labelSx}>
                  {t('category:title.upload image')}
                </Typography>
                <Box
                  sx={{
                    background: alpha(
                      appColors.blueGreyishLight[80],
                      0.04
                    ),
                    border: `1px dashed ${alpha(
                      appColors.blueGreyishLight[80],
                      0.25
                    )}`,
                    borderRadius: '6px',
                    p: 2.5,
                    textAlign: 'center',
                  }}
                >
                  {(selectedImage || data?.imageUrl) && (
                    <Box sx={{ mb: 2 }}>
                      <Box
                        alt="Preview"
                        component="img"
                        src={
                          selectedImage
                            ? URL.createObjectURL(selectedImage)
                            : data?.imageUrl
                        }
                        sx={{
                          borderRadius: '6px',
                          height: 120,
                          objectFit: 'cover',
                          width: '100%',
                        }}
                      />
                    </Box>
                  )}

                  <Button
                    component="label"
                    startIcon={<CloudUploadOutlinedIcon />}
                    sx={{
                      borderColor: alpha('#2563EB', 0.3),
                      borderRadius: '6px',
                      color: '#2563EB',
                      fontWeight: 600,
                      textTransform: 'none',
                      '&:hover': {
                        background: alpha('#2563EB', 0.05),
                        borderColor: alpha('#2563EB', 0.5),
                      },
                    }}
                    variant="outlined"
                  >
                    {selectedImage || data?.imageUrl
                      ? 'Change Image'
                      : 'Choose Image'}
                    <input
                      hidden
                      onChange={handleImageChange}
                      type="file"
                    />
                  </Button>

                  {isImageUploading && (
                    <Box sx={{ mt: 1.5 }}>
                      <CircularProgress
                        size={18}
                        sx={{ color: '#2563EB' }}
                      />
                    </Box>
                  )}
                  {selectedImage && (
                    <Typography
                      sx={{
                        color: alpha('#142352', 0.5),
                        fontSize: '0.75rem',
                        mt: 1,
                      }}
                    >
                      {selectedImage.name}
                    </Typography>
                  )}
                </Box>
              </Grid>
            )}
          </Grid>
        </Box>
      </DialogContent>

      {/* Footer */}
      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
          <Button
            onClick={() => {
              dispatch(restore());
              handleCloseDialog();
            }}
            sx={{
              borderColor: '#CBD5E1',
              borderRadius: '8px',
              color: '#475569',
              fontWeight: 600,
              height: 40,
              minWidth: 110,
              px: 3,
              textTransform: 'none',
              '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
            }}
            variant="outlined"
          >
            {t('common:cancel')}
          </Button>

          <Button
            disabled={!formValid || isBusy}
            sx={{
              background: HEADER_GRADIENT,
              borderRadius: '8px',
              boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
              color: '#fff',
              fontWeight: 700,
              height: 40,
              minWidth: 110,
              px: 3,
              textTransform: 'none',
              '&:hover': { opacity: 0.9 },
              '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' },
            }}
            type="submit"
            variant="contained"
          >
            {isBusy && (
              <CircularProgress
                size={14}
                sx={{ color: '#fff', mr: 1 }}
              />
            )}
            {buttonText}
          </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(NewProduct);
